parameters.jsCode:
// Get all incoming items
const items = $input.all();

// Group container
const grouped = {};

// Loop through each item
for (const item of items) {
  const data = item.json;
  const copy = data.Copy;

  // Initialize group if it doesn't exist
  if (!grouped[copy]) {
    grouped[copy] = {
      Copy: copy,
      submittedAt: data.submittedAt,
      variants: data.Variants,
      Checkboxes: []
    };
  }

  // Push checkbox + id into array
  grouped[copy].Checkboxes.push({
    Checkbox: data.Checkboxes,
    id: data.id
  });
}

// Convert grouped object back to array format n8n expects
return Object.values(grouped).map(group => ({
  json: group
}));

// Assuming your input JSON array is passed as the first item, e.g. via a previous Set or HTTP node.
// For example: [ { id: "...", name: "...", ... }, { ... } ]

// Get the full array from the first input item
const data = $input.first().json.data;

// Map to an array of { id, name } objects
const slim = data.map(item => {
  return {
    id: item.id,
    name: item.name,
  };
});

// Return as a single item whose json key “items” contains the array.
// (You could also just return one of them, or restructure differently.)
return [
  {
    json: {
      items: slim,
    },
  }
];

