const slim = data.map(item => {
  return {
    id: item.id,
    name: item.name,
  };
});

// Return as a single item whose json key “items” contains the array.
// (You could also just return one of them, or restructure differently.)
return [
  {
    json: {
      items: slim,
    },
  }
];

